/**
 * @param {number} turnedOn
 * @return {string[]}
 */
var readBinaryWatch = function(turnedOn) {
    const res = [];

    const toTime = (s) => {
        let hours = 0;
        if (s[0] === '1') hours += 8;
        if (s[1] === '1') hours += 4;
        if (s[2] === '1') hours += 2;
        if (s[3] === '1') hours += 1;

        let minutes = 0;
        if (s[4] === '1') minutes += 32;
        if (s[5] === '1') minutes += 16;
        if (s[6] === '1') minutes += 8;
        if (s[7] === '1') minutes += 4;
        if (s[8] === '1') minutes += 2;
        if (s[9] === '1') minutes += 1;

        if (hours >= 12 || minutes >= 60) {
            return null;
        }

        return hours + ':' + minutes.toString().padStart(2, '0');
    };

    const dfs = (left, cur) => {
        if (cur.length === 10) {
            if (left === 0) {
                const time = toTime(cur);
                if (time) {
                    res.push(time);
                }
            }
            return;
        }

        if (left > 0) {
            dfs(left - 1, cur + '1');
        }
        dfs(left, cur + '0');
    };

    dfs(turnedOn, '');

    return res;
};
